# PTX source for MSE mean reduction (fp16 inputs, fp16 output)
PTX_SOURCE = r'''
.version 8.0
.target sm_80
.address_size 64

.visible .entry mse_kernel(
    .param .u64 pred,
    .param .u64 target,
    .param .u64 out,
    .param .u32 N
)
{
    // -----------------------
    // Register declarations
    // -----------------------
    .reg .u64 %pred_ptr, %target_ptr, %out_ptr;
    .reg .u32 %n;
    .reg .u32 %gridDimX, %blockDimX, %total_threads;
    .reg .u32 %tid, %bid, %lane;
    .reg .u32 %idx;
    .reg .f16 %p_f16, %t_f16;
    .reg .f32 %p_f32, %t_f32, %diff, %sq, %sum, %temp, %n_f32, %inv_n, %mean_f32;
    .reg .f16 %mean_f16;
    .reg .pred %p_done;

    // -----------------------
    // Load kernel parameters
    // -----------------------
    ld.param.u64 %pred_ptr,   [pred];
    ld.param.u64 %target_ptr, [target];
    ld.param.u64 %out_ptr,    [out];
    ld.param.u32 %n,          [N];

    // -----------------------
    // Built‑in thread indices
    // -----------------------
    mov.u32 %tid, %tid.x;               // threadIdx.x
    mov.u32 %bid, %blockIdx.x;          // blockIdx.x
    mov.u32 %gridDimX, %gridDim.x;
    mov.u32 %blockDimX, %blockDim.x;

    // Global thread id
    mad.lo.u32 %tid, %bid, %blockDimX, %tid;

    // Total number of threads in the grid
    mul.lo.u32 %total_threads, %gridDimX, %blockDimX;

    // -----------------------
    // Initialize accumulator
    // -----------------------
    mov.f32 %sum, 0f00000000;

    // -----------------------
    // Main reduction loop over N elements
    // -----------------------
    mov.u32 %idx, %tid;
LOOP_START:
    setp.ge.u32 %p_done, %idx, %n;
    @%p_done bra DONE_LOOP;

    // Load prediction (fp16)
    mul.wide.u32 %r1, %idx, 2;               // offset in bytes
    add.u64 %r2, %pred_ptr, %r1;
    ld.global.f16 %p_f16, [%r2];

    // Load target (fp16)
    mul.wide.u32 %r3, %idx, 2;
    add.u64 %r4, %target_ptr, %r3;
    ld.global.f16 %t_f16, [%r4];

    // Convert to fp32 for accumulation
    cvt.f32.f16 %p_f32, %p_f16;
    cvt.f32.f16 %t_f32, %t_f16;

    // (p - t)^2
    sub.f32 %diff, %p_f32, %t_f32;
    mul.f32 %sq, %diff, %diff;
    add.f32 %sum, %sum, %sq;

    // Next index
    add.u32 %idx, %idx, %total_threads;
    bra LOOP_START;
DONE_LOOP:

    // -----------------------
    // Shared‑memory reduction
    // -----------------------
    .shared .align 4 .b32 sdata[256];

    // lane = threadIdx.x (original threadIdx before global conversion)
    mov.u32 %lane, %tid.x;
    st.shared.f32 [sdata+%lane*4], %sum;

    bar.sync 0;

    // Unrolled tree reduction (assumes blockDim.x == 256)
    @%lane < 128 {
        ld.shared.f32 %temp, [sdata+(%lane+128)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 64 {
        ld.shared.f32 %temp, [sdata+(%lane+64)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 32 {
        ld.shared.f32 %temp, [sdata+(%lane+32)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 16 {
        ld.shared.f32 %temp, [sdata+(%lane+16)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 8 {
        ld.shared.f32 %temp, [sdata+(%lane+8)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 4 {
        ld.shared.f32 %temp, [sdata+(%lane+4)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 2 {
        ld.shared.f32 %temp, [sdata+(%lane+2)*4];
        add.f32 %sum, %sum, %temp;
        st.shared.f32 [sdata+%lane*4], %sum;
    }
    bar.sync 0;
    @%lane < 1 {
        ld.shared.f32 %temp, [sdata+1*4];
        add.f32 %sum, %sum, %temp;
    }

    // -----------------------
    // Compute mean and write result (only thread 0)
    // -----------------------
    @%lane == 0 {
        cvt.f32.u32 %n_f32, %n;
        rcp.approx.f32 %inv_n, %n_f32;        // 1/N
        mul.f32 %mean_f32, %sum, %inv_n;      // mean
        cvt.f16.f32 %mean_f16, %mean_f32;     // back to fp16
        st.global.f16 [%out_ptr], %mean_f16;
    }

    ret;
}
'''

class ModelNew:
    def __init__(self):
        # Load PTX module using the provided harness
        self.module = ptx_load(PTX_SOURCE)

    def __call__(self, predictions, targets):
        import torch
        # Total number of elements
        N = predictions.numel()
        # Allocate output scalar (fp16)
        out = torch.empty((), dtype=torch.float16, device=predictions.device)
        # Launch configuration: 256 threads per block
        block = (256, 1, 1)
        grid = ((N + block[0] - 1) // block[0], 1, 1)
        # Prepare arguments: raw pointers and element count
        args = [predictions.data_ptr(), targets.data_ptr(), out.data_ptr(), N]
        # Launch the kernel via the harness
        ptx_launch(self.module, "mse_kernel", grid, block, args)
        return out
